select count(*) as type_ids,
 count(*) filter (where coalesce(trim(t.type_year_to),'')='') as sans_fin_texte,
 count(*) filter (where t.type_year_to_i is null) as sans_fin_entier,
 count(*) filter (where m.modele_year_to is null) as modele_sans_fin,
 min(t.type_year_from) as debut_min, max(t.type_year_from) as debut_max
from auto_type t left join auto_modele m on m.modele_id::text = t.type_modele_id::text
where t.type_id::text in ('57','470','472','4426','5260','5607','6300','6666','6675','6695','6710','7247','8454','8685','9931','10271','11253','11710','13927','15716','16331','16889','16914','18794','18899','18901','19203','19215','19359','19620','19675','19861','19978','20347','20643','22306','22473','22651','22653','23175','23177','23464','24514','24515','26491','26605','28149','28183','29603','29956','30326','30359','30975','31083','31163','31278','31606','32043','32819','32825','33353','33395','33399','33715','34724','34725','35269','55636','55886','56223','56250','57281','57282','58144','58615','58667','58791','59023','59024','59120','65057','66076','66087','68601','75021','75023');
